This is the vanilla extracted tool response: // =============================================================================
// JWT Token Manager — Server-only module for TransJakarta API auth
// =============================================================================
// Handles guest JWT acquisition, caching, and auto-refresh on 401.
// Runs exclusively on the server ($lib/server/ enforced by SvelteKit).
// Compatible with Cloudflare Workers runtime (no Node.js APIs).
// =============================================================================

import { decodeJwt } from 'jose';

const API_BASE = 'https://tijeapi.transjakarta.co.id';
const DEVICE_ID = 'tj-webapp-a1b2c3d4e5f6';

/** Headers required by ALL TransJakarta API requests */
const BASE_HEADERS: Record<string, string> = {
	'Content-Type': 'application/json',
	Accept: 'application/json',
	'User-Agent': 'okhttp/4.12.0',
	'X-App-OS': 'android',
	'X-App-Version': '2.10.2',
	'X-Device-ID': DEVICE_ID
};

// ---------------------------------------------------------------------------
// Module-level token cache (per isolate on Workers, singleton in Node)
// ---------------------------------------------------------------------------

let cachedToken: string | null = null;
let tokenExpiry: number = 0; // epoch seconds

// ---------------------------------------------------------------------------
// Token helpers
// ---------------------------------------------------------------------------

/** Check if the cached token is still valid (with 60s safety margin) */
function isTokenValid(): boolean {
	if (!cachedToken) return false;
	const now = Math.floor(Date.now() / 1000);
	return now < tokenExpiry - 60;
}

/** Fetch a fresh guest token from the TJ API */
async function fetchGuestToken(): Promise<string> {
	const res = await fetch(`${API_BASE}/v1/auth/login/guest`, {
		method: 'POST',
		headers: BASE_HEADERS,
		body: JSON.stringify({
			device_id: DEVICE_ID
		})
	});

	if (!res.ok) {
		const text = await res.text();
		throw new Error(`Guest login failed (${res.status}): ${text}`);
	}

	const json = await res.json();
	const token: string = (json as Record<string, unknown>)?.token as string
		?? (json as { data?: { token?: string } })?.data?.token
		?? '';

	if (!token) {
		throw new Error(`Guest login returned no token: ${JSON.stringify(json)}`);
	}

	// Decode to extract expiry
	try {
		const claims = decodeJwt(token);
		tokenExpiry = (claims.exp as number) ?? 0;
	} catch {
		// If decode fails, assume 24h validity as fallback
		tokenExpiry = Math.floor(Date.now() / 1000) + 86400;
	}

	cachedToken = token;
	return token;
}

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Returns a valid JWT token, fetching a new one if needed.
 */
export async function getToken(): Promise<string> {
	if (isTokenValid()) {
		return cachedToken!;
	}
	return fetchGuestToken();
}

/**
 * Invalidates the cached token, forcing the next request to re-authenticate.
 */
export function invalidateToken(): void {
	cachedToken = null;
	tokenExpiry = 0;
}

/**
 * Makes an authenticated request to the TransJakarta API.
 * Automatically injects auth headers and retries once on 401.
 *
 * @param path  - API path (e.g. "/v1/bus-stop?latitude=..."). Must start with "/".
 * @param options - Standard RequestInit overrides (method, body, etc.)
 * @returns The raw Response from the TJ API
 */
export async function apiRequest(
	path: string,
	options: RequestInit = {}
): Promise<Response> {
	const token = await getToken();

	const headers: Record<string, string> = {
		...BASE_HEADERS,
		Authorization: `Bearer ${token}`,
		...(options.headers as Record<string, string> | undefined)
	};

	const url = `${API_BASE}${path}`;

	let res = await fetch(url, {
		...options,
		headers
	});

	// On 401, refresh token and retry exactly once
	if (res.status === 401) {
		invalidateToken();
		const newToken = await getToken();
		headers['Authorization'] = `Bearer ${newToken}`;

		res = await fetch(url, {
			...options,
			headers
		});
	}

	return res;
}
