This is the vanilla extracted tool response: // =============================================================================
// MQTT Connection Manager — Svelte Store
// Manages WebSocket connection to TransJakarta MQTT broker for real-time
// bus position streaming.
// =============================================================================

import { writable, derived } from 'svelte/store';
import mqtt from 'mqtt';
import type { Bus, ConnectionStatus } from '$lib/types';

// --- Constants ---
const BROKER_URL = 'wss://mqtt.tj.co.id:8084/mqtt';

// --- Writable Stores ---

/** Bus positions map: bus_body_no → Bus (O(1) upsert) */
export const busPositions = writable<Map<string, Bus>>(new Map());

/** Current connection status */
export const connectionStatus = writable<ConnectionStatus>({
	mode: 'disconnected',
	lastUpdate: 0,
	messageCount: 0
});

// --- Derived Stores ---

/** Bus list as array — for rendering in {#each} blocks */
export const busList = derived(busPositions, ($map) => Array.from($map.values()));

/** Total number of tracked buses */
export const busCount = derived(busPositions, ($map) => $map.size);

// --- Module-level State ---
let client: mqtt.MqttClient | null = null;
let subscribedTopics: string[] = [];

// --- Public API ---

/**
 * Connect to the MQTT broker. No-op if already connected.
 * Auto-reconnects every 5 s on disconnect (handled by mqtt.js).
 */
export function connectMqtt(): void {
	if (client?.connected) return;

	// Tear down stale client before creating a new one
	disconnectMqtt();

	client = mqtt.connect(BROKER_URL, {
		// Anonymous connection — no username/password needed
		protocolVersion: 4,
		keepalive: 30,
		reconnectPeriod: 5000, // Auto-reconnect every 5 s
		connectTimeout: 10000,
		clean: true
	});

	client.on('connect', () => {
		connectionStatus.update((s) => ({ ...s, mode: 'mqtt' }));
		console.log('[MQTT] Connected to broker');

		// Re-subscribe on reconnect
		if (subscribedTopics.length > 0) {
			subscribeToTopics(subscribedTopics);
		}
	});

	client.on('message', (_topic: string, payload: Buffer) => {
		try {
			const data: unknown = JSON.parse(payload.toString());
			handleBusUpdate(data);
		} catch {
			// Silently ignore malformed messages
		}
	});

	client.on('error', (err: Error) => {
		console.error('[MQTT] Error:', err.message);
	});

	client.on('close', () => {
		connectionStatus.update((s) => ({ ...s, mode: 'disconnected' }));
		console.log('[MQTT] Connection closed');
	});

	client.on('reconnect', () => {
		console.log('[MQTT] Reconnecting...');
	});
}

/**
 * Subscribe to one or more MQTT topics.
 * Topics are remembered and re-subscribed on reconnect.
 */
export function subscribeToTopics(topics: string[]): void {
	subscribedTopics = topics;
	if (!client?.connected) return;

	for (const topic of topics) {
		client.subscribe(topic, { qos: 0 }, (err) => {
			if (err) console.error(`[MQTT] Subscribe error for ${topic}:`, err);
		});
	}
	console.log(`[MQTT] Subscribed to ${topics.length} topics`);
}

/**
 * Disconnect from the broker and clear topic subscriptions.
 */
export function disconnectMqtt(): void {
	if (client) {
		client.end(true);
		client = null;
	}
	subscribedTopics = [];
	connectionStatus.update((s) => ({ ...s, mode: 'disconnected' }));
}

/**
 * Full cleanup — disconnect + reset all store state.
 * Call on component destroy / page navigation away.
 */
export function cleanup(): void {
	disconnectMqtt();
	busPositions.set(new Map());
	connectionStatus.set({ mode: 'disconnected', lastUpdate: 0, messageCount: 0 });
}

// --- Internal ---

/**
 * Parse an incoming MQTT message and upsert into busPositions.
 * Messages must have at least bus_body_no, latitude, longitude.
 */
function handleBusUpdate(data: unknown): void {
	if (!data || typeof data !== 'object') return;

	const record = data as Record<string, unknown>;
	const busBodyNo = record.bus_body_no;
	const lat = record.latitude;
	const lng = record.longitude;

	// Minimum fields required for a valid bus position
	if (typeof busBodyNo !== 'string' || typeof lat !== 'number' || typeof lng !== 'number') return;

	busPositions.update((map) => {
		const newMap = new Map(map);
		newMap.set(busBodyNo, record as unknown as Bus);
		return newMap;
	});

	connectionStatus.update((s) => ({
		...s,
		lastUpdate: Date.now(),
		messageCount: s.messageCount + 1
	}));
}

