    creator: { '@type': 'Person', name: 'Mugni Hadi' },
  }}
/>

<div class="relative h-full w-full">
  <!-- Map fills entire space -->
  <div class="absolute inset-0" style="z-index: var(--z-map);">
    {#if MapContainer}
      <MapContainer {targetLat} {targetLng} {targetLabel} />
    {:else if mapLoadError}
      <div class="flex h-full items-center justify-center" style="background-color: var(--color-base);">
        <p class="text-sm" style="color: var(--color-error);">Failed to load map</p>
      </div>
    {:else}
      <!-- Loading placeholder while map chunk downloads -->
      <div class="flex h-full items-center justify-center" style="background-color: var(--color-base);">
        <div class="flex flex-col items-center gap-3">
          <div class="h-8 w-8 animate-spin rounded-full border-2 border-t-transparent"
            style="border-color: var(--color-accent); border-top-color: transparent;"></div>
          <p class="text-sm" style="color: var(--color-text-muted);">Loading map…</p>
        </div>
      </div>
    {/if}
  </div>

  <!-- Connection badge overlay (top-left, offset past side panel on desktop) -->
  <div
    class="absolute top-3 left-3 md:left-[376px] lg:left-[436px]"
    style="z-index: var(--z-overlay);"
  >
    <ConnectionBadge />
  </div>

  <!-- Side panel / Bottom sheet overlay -->
  <div class="pointer-events-none absolute inset-0" style="z-index: var(--z-panel);">
    <SidePanel>
      {#snippet header()}
        <RouteFilterBar onOpenFilter={() => (filterPopupOpen = true)} />
      {/snippet}
      {#if panelMode === 'entry'}
        <!-- Entry panel with nearby stops + CTAs -->
        <HomeEntryPanel
          busCount={$busCount}
          filteredCount={isFiltered ? $filteredBusCount : undefined}
          {isConnected}
          onSwitchToFullNetwork={switchToFullNetwork}
          onTrackAction={trackFirst}
        >
          <NearbyVehiclesPreview
            onRetry={() => homeEntry.retry()}
          />
        </HomeEntryPanel>
      {:else}
        <!-- Full network mode (bus list with back button) -->
        <div class="space-y-3 p-4">
          <div class="flex items-center gap-3">
            <button
              type="button"
              class="back-to-entry-btn"
              onclick={switchToEntry}
            >
              {HOME_COPY.fullNetwork.backToEntry}
            </button>
          </div>
          <div class="flex items-center justify-between">
            <h2 class="text-base font-semibold" style="color: var(--color-text-primary);">
              {HOME_COPY.fullNetwork.title}
            </h2>
            <span class="font-mono text-sm" style="color: var(--color-text-secondary);">
              {#if isFiltered}
                {$filteredBusCount}/{$busCount} tracked
              {:else}
                {$busCount} tracked
              {/if}
            </span>
          </div>

          {#if $filteredBusList.length === 0}
            <div class="fleet-shimmer-container" role="status" aria-label="Loading fleet data">
              <p class="fleet-shimmer-label">
                {HOME_COPY.fullNetwork.connecting}
              </p>
              {#each [1, 2, 3] as _i}
                <div class="fleet-skeleton-card">
                  <div class="fleet-skeleton-dot"></div>
                  <div class="fleet-skeleton-lines">
                    <div class="fleet-skeleton-line" style="width: 60%;"></div>
                    <div class="fleet-skeleton-line short" style="width: 40%;"></div>
                  </div>
                  <div class="fleet-skeleton-badge"></div>
                </div>
              {/each}
            </div>
          {:else}
            <div class="space-y-2">
              {#each $filteredBusList.slice(0, 20) as bus (bus.bus_body_no)}
                <div
                  class="flex items-center gap-3 rounded-lg p-2 transition-colors"
                  style="background-color: var(--color-surface-elevated);"
                >
                  <div
                    class="h-3 w-3 shrink-0 rounded-full"
                    style="background-color: #{bus.route_color || '3b82f6'};"
                  ></div>
                  <div class="min-w-0 flex-1">
                    <div class="flex items-center gap-2">
                      <span
                        class="text-sm font-medium"
                        style="color: var(--color-text-primary);"
                      >
                        {bus.route_code}
                      </span>
                      <span
                        class="truncate text-xs"
                        style="color: var(--color-text-secondary);"
                      >
                        {bus.route_name}
                      </span>
                    </div>
                    <div
                      class="flex items-center gap-2 font-mono text-xs"
                      style="color: var(--color-text-muted);"
                    >
                      <span>{bus.bus_body_no}</span>
                      <span>·</span>
                      <span>{bus.speed} km/h</span>
                    </div>
                  </div>
                  <span
                    class="shrink-0 rounded px-1.5 py-0.5 text-xs"
                    style="background-color: color-mix(in srgb, #{bus.route_color || '3b82f6'} 15%, transparent); color: #{bus.route_text_color || 'ffffff'};"
                  >
                    {bus.type}
                  </span>
                </div>
              {/each}
              {#if $filteredBusList.length > 20}
                <p class="text-center text-xs" style="color: var(--color-text-muted);">
                  + {$filteredBusList.length - 20} more buses
                </p>
              {/if}
            </div>
          {/if}
        </div>
      {/if}
    </SidePanel>
  </div>

  <!-- Route filter popup (modal/bottom-sheet) -->
