This is the vanilla extracted tool response: import { json } from '@sveltejs/kit';
import type { RequestHandler } from './$types';
import { apiRequest } from '$lib/server/jwt';

/**
 * POST /api/buses — Get buses near a location + MQTT topics
 * Body: { latitude, longitude, radius, event: "change_loc" }
 */
export const POST: RequestHandler = async ({ request }) => {
	try {
		const body = await request.json();
		const response = await apiRequest('/v1/bus', {
			method: 'POST',
			body: JSON.stringify(body)
		});
		const data = await response.json();
		return json(data, { status: response.status });
	} catch (error) {
		const message = error instanceof Error ? error.message : 'Proxy error';
		return json({ code: 500, message, data: null }, { status: 500 });
	}
};

/**
 * Fields to strip from each bus in GET responses.
 * The `stops` field contains per-bus stop arrays (avg 29.5 stops/bus, 115k+ total)
 * accounting for 97.5% of response size (29.4 MB → 2.1 MB after removal).
 * Client components never read per-bus stops — they use next_stops/prev_stops strings.
 */
const HEAVY_BUS_FIELDS = ['stops'] as const;

/**
 * GET /api/buses?latitude=&longitude=&radius= — Get ALL buses in radius
 *
 * Strips heavy fields (stops arrays) before responding to reduce payload
 * from ~29 MB to ~2 MB, preventing Cloudflare Workers CPU/memory limits (Error 1102).
 */
export const GET: RequestHandler = async ({ url }) => {
	try {
		const latitude = url.searchParams.get('latitude') ?? '';
		const longitude = url.searchParams.get('longitude') ?? '';
		const radius = url.searchParams.get('radius') ?? '';

		const params = new URLSearchParams({ latitude, longitude, radius });
		const response = await apiRequest(`/v1/bus?${params.toString()}`);
		const data = await response.json();

		// Strip heavy per-bus fields to reduce response size by ~93%
		if (data && typeof data === 'object' && Array.isArray((data as Record<string, unknown>).data)) {
			const buses = (data as Record<string, unknown>).data as Record<string, unknown>[];
			for (const bus of buses) {
				for (const field of HEAVY_BUS_FIELDS) {
					delete bus[field];
				}
			}
		}

		return json(data, { status: response.status });
	} catch (error) {
		const message = error instanceof Error ? error.message : 'Proxy error';
		return json({ code: 500, message, data: null }, { status: 500 });
	}
};

