  import { onMount, onDestroy } from 'svelte';
  import SEO from '$lib/components/SEO.svelte';
  import SidePanel from '$lib/components/SidePanel.svelte';
  import ConnectionBadge from '$lib/components/ConnectionBadge.svelte';
  import HomeEntryPanel from '$lib/components/home/HomeEntryPanel.svelte';
  import NearbyVehiclesPreview from '$lib/components/home/NearbyVehiclesPreview.svelte';
  import RouteFilterBar from '$lib/components/RouteFilterBar.svelte';
  import RouteFilterPopup from '$lib/components/RouteFilterPopup.svelte';
  import { initTracking, destroyTracking } from '$lib/stores';
  import { initRouteMetadata } from '$lib/stores';
  import { busCount, connectionStatus } from '$lib/stores';
  import { activeRouteFilters, setRouteFilters, filteredBusList, filteredBusCount } from '$lib/stores';
  import { createHomeEntryStore } from '$lib/stores/home-entry.svelte';
  import { HOME_COPY } from '$lib/config/copy';
  import { trackHomeEvent, createFirstActionTracker } from '$lib/telemetry/home';
  import type { Component } from 'svelte';
  import type { HomePanelMode } from '$lib/types/home';

  // Lazy-load the heavy MapContainer (~1.4MB maplibre-gl)
  let MapContainer: Component | null = $state(null);
  let mapLoadError = $state(false);

  const MODE_PREF_KEY = 'tj-home-mode-pref';
  let panelMode = $state<HomePanelMode>('entry');
  const homeEntry = createHomeEntryStore();
  const trackFirst = createFirstActionTracker();

  // Track whether route filter URL sync should be active
  // (skip the first subscription fire that happens before onMount reads URL params)
  let routeFilterUrlReady = false;
  let unsubRouteFilters: (() => void) | null = null;
  let filterPopupOpen = $state(false);

  // Deep-link target location (set from "View on Map" in stop detail)
  let targetLat = $state<number | undefined>(undefined);
  let targetLng = $state<number | undefined>(undefined);
  let targetLabel = $state<string | undefined>(undefined);

  function switchToFullNetwork() {
    trackHomeEvent({ type: 'home_mode_changed', from: 'entry', to: 'full-network' });
    trackFirst('full_network');
    panelMode = 'full-network';
    if (typeof window !== 'undefined') {
      const url = new URL(window.location.href);
      url.searchParams.set('mode', 'fleet');
      history.replaceState(null, '', url.toString());
    }
    try { localStorage.setItem(MODE_PREF_KEY, 'full-network'); } catch {}
  }

  function switchToEntry() {
    trackHomeEvent({ type: 'home_mode_changed', from: 'full-network', to: 'entry' });
    panelMode = 'entry';
    if (typeof window !== 'undefined') {
      const url = new URL(window.location.href);
      url.searchParams.delete('mode');
      history.replaceState(null, '', url.toString());
    }
    try { localStorage.removeItem(MODE_PREF_KEY); } catch {}
  }

  let isConnected = $derived($connectionStatus.mode !== 'disconnected');
  let isFiltered = $derived($activeRouteFilters.size > 0);

  onMount(async () => {
    initTracking();
    initRouteMetadata();

    // Deep-link: ?mode=fleet opens directly into full-network panel
    // Priority: URL param > localStorage preference > default (entry)
    const params = new URL(window.location.href).searchParams;
    if (params.get('mode') === 'fleet') {
      panelMode = 'full-network';
    } else {
      try {
        if (localStorage.getItem(MODE_PREF_KEY) === 'full-network') {
          panelMode = 'full-network';
        }
      } catch {}
    }

    // Deep-link: ?routes=4C,13,M11 opens with route filters pre-applied
    // Priority: URL param > localStorage (setRouteFilters also persists to localStorage)
    const routesParam = params.get('routes');
    if (routesParam) {
      const labels = routesParam.split(',').filter(Boolean);
      if (labels.length > 0) {
        setRouteFilters(labels);
      }
    }

    // Deep-link: ?lat=X&lng=Y centers map on a specific location (e.g., "View on Map" from stop detail)
    const latParam = parseFloat(params.get('lat') ?? '');
    const lngParam = parseFloat(params.get('lng') ?? '');
    if (!isNaN(latParam) && !isNaN(lngParam)) {
      targetLat = latParam;
      targetLng = lngParam;
      targetLabel = params.get('stop') ?? undefined;
    }

    // Subscribe to filter changes → sync back to URL via replaceState
    routeFilterUrlReady = true;
    unsubRouteFilters = activeRouteFilters.subscribe((filters) => {
      if (!routeFilterUrlReady) return;
      const url = new URL(window.location.href);
      if (filters.size > 0 && filters.size < 10) {
        url.searchParams.set('routes', [...filters].join(','));
      } else {
        url.searchParams.delete('routes');
      }
      history.replaceState(null, '', url.toString());
    });

    // Initialize user location tracking (feeds nearby-vehicles store)
    homeEntry.init();

    try {
      const mod = await import('$lib/components/MapContainer.svelte');
      MapContainer = mod.default;
    } catch {
      mapLoadError = true;
    }
  });

  onDestroy(() => {
    destroyTracking();
    unsubRouteFilters?.();
  });
</script>

