This is the vanilla extracted tool response: // =============================================================================
// Connection Orchestrator
// Coordinates between MQTT (primary) and REST polling (fallback) for
// real-time bus tracking. Handles initial setup, auto-failover, and teardown.
// =============================================================================

import { connectMqtt, disconnectMqtt, connectionStatus, subscribeToTopics } from './mqtt';
import { startPolling, stopPolling } from './rest-polling';
import type { BusPostResponse, ApiResponse } from '$lib/types';

// --- Constants ---
const JAKARTA_LAT = -6.2088;
const JAKARTA_LNG = 106.8456;

// Track the subscription so we can unsubscribe on destroy
let unsubConnectionStatus: (() => void) | null = null;

// --- Public API ---

/**
 * Initialize the real-time bus tracking connection.
 * 1. Fetch initial bus data + MQTT topics from POST /api/buses
 * 2. Try to connect via MQTT
 * 3. If MQTT fails, fall back to REST polling
 */
export async function initTracking(lat?: number, lng?: number): Promise<void> {
	const latitude = lat ?? JAKARTA_LAT;
	const longitude = lng ?? JAKARTA_LNG;

	try {
		// Step 1: Get bus data + MQTT topics
		const response = await fetch('/api/buses', {
			method: 'POST',
			headers: { 'Content-Type': 'application/json' },
			body: JSON.stringify({
				latitude,
				longitude,
				radius: 1,
				event: 'change_loc'
			})
		});

		if (!response.ok) throw new Error(`HTTP ${response.status}`);

		const result: ApiResponse<BusPostResponse> = await response.json();

		if (result.code === 200 && result.data?.topics?.length > 0) {
			// Step 2: Connect MQTT and subscribe to topics
			connectMqtt();
			subscribeToTopics(result.data.topics);
			console.log(`[Connection] MQTT initialized with ${result.data.topics.length} topics`);
		} else {
			throw new Error('No MQTT topics received');
		}
	} catch (error) {
		console.warn('[Connection] MQTT init failed, falling back to REST polling:', error);
		startPolling({ latitude, longitude });
	}

	// Monitor connection status — auto-switch between MQTT and REST
	// Clean up any previous subscription first
	if (unsubConnectionStatus) {
		unsubConnectionStatus();
	}

	unsubConnectionStatus = connectionStatus.subscribe((status) => {
		if (status.mode === 'disconnected') {
			// MQTT disconnected — start REST polling as fallback
			startPolling({ latitude, longitude });
		}
	});
}

/**
 * Switch from REST polling to MQTT when connection is restored.
 */
export function switchToMqtt(topics: string[]): void {
	stopPolling();
	connectMqtt();
	subscribeToTopics(topics);
}

/**
 * Tear down all connections and clean up subscriptions.
 */
export function destroyTracking(): void {
	if (unsubConnectionStatus) {
		unsubConnectionStatus();
		unsubConnectionStatus = null;
	}
	disconnectMqtt();
	stopPolling();
}
