import type { Bus, ApiResponse } from '$lib/types';

// --- Constants ---
const DEFAULT_INTERVAL = 10000; // 10 seconds
const JAKARTA_LAT = -6.2088;
const JAKARTA_LNG = 106.8456;
const DEFAULT_RADIUS = 50; // km — get all buses

// --- Module-level State ---
let pollingTimer: ReturnType<typeof setInterval> | null = null;
let isPolling = false;

// --- Public API ---

/**
 * Start polling the REST API at a fixed interval.
 * No-op if already polling.
 */
export function startPolling(options?: {
	interval?: number;
	latitude?: number;
	longitude?: number;
	radius?: number;
}): void {
	if (isPolling) return;

	const interval = options?.interval ?? DEFAULT_INTERVAL;
	const lat = options?.latitude ?? JAKARTA_LAT;
	const lng = options?.longitude ?? JAKARTA_LNG;
	const radius = options?.radius ?? DEFAULT_RADIUS;

	isPolling = true;
	connectionStatus.update((s) => ({ ...s, mode: 'rest-polling' }));
	console.log(`[REST] Starting polling every ${interval / 1000}s`);

	// Fetch immediately, then start interval
	fetchBuses(lat, lng, radius);
	pollingTimer = setInterval(() => fetchBuses(lat, lng, radius), interval);
}

/**
 * Stop the polling loop.
 */
export function stopPolling(): void {
	if (pollingTimer) {
		clearInterval(pollingTimer);
		pollingTimer = null;
	}
	isPolling = false;
	console.log('[REST] Polling stopped');
}

/**
 * Check whether polling is currently active.
 */
export function isCurrentlyPolling(): boolean {
	return isPolling;
}

// --- Internal ---

/**
 * Fetch bus positions from the REST API and update the shared store.
 */
async function fetchBuses(lat: number, lng: number, radius: number): Promise<void> {
	try {
		const url = `/api/buses?latitude=${lat}&longitude=${lng}&radius=${radius}`;
		const response = await fetch(url);

		if (!response.ok) {
			console.error(`[REST] Fetch failed: ${response.status}`);
			return;
		}

		const result: ApiResponse<Bus[]> = await response.json();

		if (result.code !== 200 || !Array.isArray(result.data)) {
			console.error('[REST] Invalid response:', result.message);
			return;
		}

		// Update the shared bus positions store
		busPositions.update(() => {
			const newMap = new Map<string, Bus>();
			for (const bus of result.data) {
				if (bus.bus_body_no) {
					newMap.set(bus.bus_body_no, bus);
				}
			}
			return newMap;
		});

		connectionStatus.update((s) => ({
			...s,
			mode: 'rest-polling',
			lastUpdate: Date.now(),
			messageCount: s.messageCount + 1
		}));

		console.log(`[REST] Updated ${result.data.length} buses`);
	} catch (error) {
		console.error('[REST] Fetch error:', error);
	}
}

